"  // Generic helper to check any pos_access permission by category and key
  const checkPosAccess = (category, key) => {
    if (!business) return true;
    const userRole = String(business?.role || '').toLowerCase();
    const isSupervisor = ['brand_owner', 'master_admin', 'admin', 'manager'].includes(userRole) || userRole.includes('admin') || userRole.includes('manager');
    if (isSupervisor) return true;
    const posAccess = business?.staff_permissions?.pos_access;
    if (!posAccess) return true;
    // Check category-level visibility first
    if (posAccess?.[category]?.visible === false) return false;
    // Check specific key
    const perm = posAccess?.[category]?.[key];
    return perm !== false;
  };

  // Enforce tab security by redirecting from restricted tabs
  useEffect(() => {
    if (isAuthenticated && business) {
      if (!isTabAllowed(activeTab)) {
        const tabs = ['home', 'billing', 'live', 'digital', 'receipts', 'whatsapp', 'expenses', 'analytics', 'config', 'settings'];
        const allowed = tabs.find(t => isTabAllowed(t));
        if (allowed) {
          setActiveTab(allowed);
        }
      }

      if (activeTrayTab === 'KOT' && !checkPosAccess('KOT', 'visible')) {
        if (checkPosAccess('Billing', 'visible')) {
          setActiveTrayTab('Billing');
        }
      } else if (activeTrayTab === 'Billing' && !checkPosAccess('Billing', 'visible')) {
        if (checkPosAccess('KOT', 'visible')) {
          setActiveTrayTab('KOT');
        }
      }
    }
  }, [business, isAuthenticated, activeTab, activeTrayTab]);"

